function showMessage(text){ui.message.textContent=text;ui.message.classList.add('show');clearTimeout(showMessage.timer);showMessage.timer=setTimeout(()=>ui.message.classList.remove('show'),950)}
function updateHUD(){ui.score.textContent=String(score).padStart(4,'0');ui.chain.textContent='×'+chain;ui.time.textContent=Math.ceil(timeLeft);ui.hearts.textContent='♥ '.repeat(lives).trim()||'—';ui.phase.textContent='TIDE: '+(phase?'CORAL':'MINT');ui.phase.style.color=phase?'#ff8ba3':'#68f3e5';}
function startGame(){for(let a of [...motes,...enemies])world.remove(a.group);for(let p of particles)world.remove(p.mesh);for(let r of rings)world.remove(r.mesh);motes=[];enemies=[];particles=[];rings=[];player.position.set(0,0,0);player.rotation.set(0,0,0);score=0;lives=3;timeLeft=60;chain=1;chainTimer=0;pulseCD=0;elapsed=0;spawnTimer=1;moteTimer=.15;phase=0;hitFlash=0;camShake=0;running=true;ended=false;input={x:0,z:0};ui.intro.classList.add('hidden');ui.over.classList.add('hidden');ui.hud.classList.add('active');ui.phase.classList.add('show');for(let i=0;i<5;i++)makeMote();updateHUD();showMessage('CATCH THE CURRENT');}
function endGame(){running=false;ended=true;ui.hud.classList.remove('active');ui.phase.classList.remove('show');ui.over.classList.remove('hidden');let isBest=score>best;if(isBest){best=score;localStorage.setItem('mirrorBest',best)}document.querySelector('#resultTitle').textContent=isBest?'NEW HIGH TIDE!':'NICE CURRENT.';document.querySelector('#resultText').textContent=`You pulled in ${score} signal${score===1?'':'s'}${best?` · best run ${best}`:''}. The hunters will remember.`;}
function flipTide(){if(!running||pulseCD>0)return;phase=1-phase;pulseCD=1.35;camShake=.18;shockwave();showMessage(phase?'TIDE FLIPPED · CORAL':'TIDE FLIPPED · MINT');let center=new THREE.Vector3(player.position.x,0,player.position.z);for(let e of enemies){let away=new THREE.Vector3().subVectors(e.group.position,center);if(away.length()<6.8){away.normalize();e.vel.addScaledVector(away,8.5);e.reflected=1.7;e.stun=1.1;burst(e.group.position,0xffd987,5,2.4)}}for(let m of motes){let away=new THREE.Vector3().subVectors(m.group.position,center);if(away.length()<4.5){away.normalize();m.vel.addScaledVector(away,3)}}playerHalo.material.color.setHex(phase?0xff8ba3:0x68f3e5);playerAura.material.color.setHex(phase?0xff739b:0x68f3e5);updateHUD();}
function loseLife(){if(hitFlash>0)return;lives--;hitFlash=1.35;camShake=.38;chain=1;chainTimer=0;burst(player.position,0xff6b91,18,4);showMessage(lives?'HULL HIT — GET YOUR RHYTHM BACK':'SIGNAL LOST');updateHUD();if(lives<=0)setTimeout(()=>{if(running)endGame()},650)}
const clock=new THREE.Clock();
function update(dt){elapsed+=dt;if(!running){stars.rotation.y+=dt*.003;return}timeLeft-=dt;if(timeLeft<=0){timeLeft=0;updateHUD();endGame();return}if(chainTimer>0){chainTimer-=dt;if(chainTimer<=0)chain=1}if(pulseCD>0)pulseCD-=dt;if(hitFlash>0)hitFlash-=dt;spawnTimer-=dt;moteTimer-=dt;if(spawnTimer<=0){makeEnemy();spawnTimer=Math.max(.56,2.5-elapsed*.025)*(0.82+Math.random()*.4)}if(moteTimer<=0&&motes.length<8){makeMote();moteTimer=1.15+Math.random()*.8}
// Accelerating inertia makes movement feel like skating, but the boundary catches you cleanly.
let ix=input.x,iz=input.z;if(keys.ArrowLeft||keys.a||keys.A)ix-=1;if(keys.ArrowRight||keys.d||keys.D)ix+=1;if(keys.ArrowUp||keys.w||keys.W)iz-=1;if(keys.ArrowDown||keys.s||keys.S)iz+=1;let mag=Math.hypot(ix,iz);if(mag>1){ix/=mag;iz/=mag}player.userData.vx=(player.userData.vx||0)+ix*18*dt;player.userData.vz=(player.userData.vz||0)+iz*18*dt;let drag=Math.pow(.08,dt);player.userData.vx*=ix||iz?Math.pow(.38,dt):drag;player.userData.vz*=ix||iz?Math.pow(.38,dt):drag;let speed=Math.hypot(player.userData.vx,player.userData.vz);if(speed>6.2){player.userData.vx*=6.2/speed;player.userData.vz*=6.2/speed}player.position.x+=player.userData.vx*dt;player.position.z+=player.userData.vz*dt;let radius=Math.hypot(player.position.x,player.position.z);if(radius>9.15){let nx=player.position.x/radius,nz=player.position.z/radius;player.position.x=nx*9.15;player.position.z=nz*9.15;player.userData.vx-=nx*dt*14;player.userData.vz-=nz*dt*14}
let moving=Math.hypot(player.userData.vx,player.userData.vz);body.position.y=.56+Math.sin(elapsed*11)*.055+Math.min(moving*.013,.07);body.rotation.z=-player.userData.vx*.055;body.rotation.x=player.userData.vz*.04;playerHalo.rotation.z+=dt*(2+moving*.4);if(moving>.15)body.rotation.y=Math.atan2(player.userData.vx,player.userData.vz);
for(let i=motes.length-1;i>=0;i--){let m=motes[i];m.spin+=dt*2.7;m.group.rotation.y+=dt*1.1;m.crystal.rotation.x+=dt*1.7;m.crystal.rotation.z+=dt*.8;m.group.position.addScaledVector(m.vel,dt);m.vel.multiplyScalar(Math.pow(.55,dt));let to=new THREE.Vector2(player.position.x-m.group.position.x,player.position.z-m.group.position.z);if(to.length()<.82){let match=m.color===phase;if(match){chain=Math.min(8,chain+1);score+=100*chain;chainTimer=3.1;burst(m.group.position,orbColors[m.color],12,3);showMessage(chain>2?`CHAIN ×${chain}!`:'CLEAN CATCH +'+100*chain)}else{score+=50;chain=Math.max(1,chain-1);chainTimer=2;burst(m.group.position,orbColors[m.color],7,2);showMessage('OFF-TIDE CATCH +50')}world.remove(m.group);motes.splice(i,1);updateHUD()}else if(Math.hypot(m.group.position.x,m.group.position.z)>9.7){m.vel.multiplyScalar(-1)}}
for(let i=enemies.length-1;i>=0;i--){let e=enemies[i];e.rot+=dt*(e.reflected>0?6:2);e.group.rotation.y=e.rot;e.reflected=Math.max(0,e.reflected-dt);e.stun=Math.max(0,e.stun-dt);let dx=player.position.x-e.group.position.x,dz=player.position.z-e.group.position.z,d=Math.hypot(dx,dz)||1;if(e.stun<=0&&e.reflected<=0){let force=e.speed;e.vel.x+=(dx/d)*force*dt*2.2;e.vel.z+=(dz/d)*force*dt*2.2}e.vel.multiplyScalar(Math.pow(.74,dt));let es=Math.hypot(e.vel.x,e.vel.z);if(es>8){e.vel.multiplyScalar(8/es)}e.group.position.x+=e.vel.x*dt;e.group.position.z+=e.vel.z*dt;if(e.reflected>0&&Math.hypot(e.group.position.x,e.group.position.z)>9.2){score+=150;chain=Math.min(8,chain+1);chainTimer=3;burst(e.group.position,0xffd987,15,4);world.remove(e.group);enemies.splice(i,1);showMessage('RICOCHET +150');updateHUD();continue}if(d<.78&&hitFlash<=0){loseLife();let nX=(e.group.position.x-player.position.x)/d,nZ=(e.group.position.z-player.position.z)/d;e.vel.set(nX*5,0,nZ*5)}if(e.reflected>0&&d<.68){score+=200;chain=Math.min(8,chain+1);chainTimer=3;burst(e.group.position,0xffd987,18,4);world.remove(e.group);enemies.splice(i,1);showMessage('TURNED THE HUNT +200');updateHUD()}}
for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.life-=dt;p.mesh.position.addScaledVector(p.vel,dt);p.vel.y-=5*dt;p.mesh.scale.multiplyScalar(Math.max(0,1-dt*1.3));p.mesh.material.opacity=Math.max(0,p.life/p.max);if(p.life<=0){world.remove(p.mesh);particles.splice(i,1)}}for(let i=rings.length-1;i>=0;i--){let r=rings[i];r.life-=dt;let t=1-r.life/r.max;r.mesh.scale.setScalar(1+t*8);r.mesh.material.opacity=(1-t)*.8;if(r.life<=0){world.remove(r.mesh);rings.splice(i,1)}}
camShake=Math.max(0,camShake-dt);let sh=camShake?((Math.random()-.5)*camShake):0;camera.position.x=player.position.x*.08+sh;camera.position.z=22+player.position.z*.08+sh;camera.lookAt(player.position.x*.08,0,player.position.z*.08);stars.rotation.y+=dt*.003;updateHUD();}

